    public List<Customer> findAll(CustomerFilter filter, int offset, int limit, List<CustomerSort> sorts) {
        requireSanePage(offset, limit);
        List<Customer> page = customers.stream()
                .filter(filter.asPredicate())
                .sorted(comparatorFor(sorts))
                .skip(offset)
                .limit(limit)
                .toList();
        queryLog.recordPage(offset, limit, page.size());
        return page;
