/** What the filter matches, and how it reads a name query. */
class CustomerFilterTest {

    private static final Customer ADA =
            new Customer(1, "Ada", "Aaltonen", "ada@example.com", "Finland", CustomerStatus.ACTIVE);
    private static final Customer JOSEPHINE =
            new Customer(2, "Joséphine", "Mäkinen", "jo@example.com", "France", CustomerStatus.CLOSED);

    private static boolean matches(CustomerFilter filter, Customer customer) {
        return filter.asPredicate().test(customer);
    }

    @Test
    void emptyFilterMatchesEverything() {
        assertTrue(CustomerFilter.EMPTY.isEmpty());
        assertTrue(matches(CustomerFilter.EMPTY, ADA));
        assertTrue(matches(CustomerFilter.EMPTY, JOSEPHINE));
    }

    @Test
    void everyTermMustMatchEitherName() {
        assertTrue(matches(new CustomerFilter("ada aal", Set.of()), ADA));
        assertTrue(matches(new CustomerFilter("aal ada", Set.of()), ADA));
        assertTrue(matches(new CustomerFilter("  ada   aal  ", Set.of()), ADA));
        assertFalse(matches(new CustomerFilter("ada virtanen", Set.of()), ADA));
    }

    @Test
    void matchingIgnoresCaseAndAccentsInBothDirections() {
        assertTrue(matches(new CustomerFilter("makinen", Set.of()), JOSEPHINE));
        assertTrue(matches(new CustomerFilter("MAKINEN", Set.of()), JOSEPHINE));
        assertTrue(matches(new CustomerFilter("mäkinen", Set.of()), JOSEPHINE));
        assertTrue(matches(new CustomerFilter("josephine", Set.of()), JOSEPHINE));
        assertTrue(matches(new CustomerFilter("Joséphine", Set.of()), JOSEPHINE));
    }

    @Test
    void noStatusSelectedMeansEveryStatus() {
        CustomerFilter anyStatus = new CustomerFilter("", Set.of());
        assertTrue(matches(anyStatus, ADA));
        assertTrue(matches(anyStatus, JOSEPHINE));

        CustomerFilter closedOnly = new CustomerFilter("", Set.of(CustomerStatus.CLOSED));
        assertFalse(matches(closedOnly, ADA));
        assertTrue(matches(closedOnly, JOSEPHINE));
    }

    @Test
    void bothPartsHaveToMatch() {
        CustomerFilter filter = new CustomerFilter("ada", Set.of(CustomerStatus.CLOSED));
        assertFalse(matches(filter, ADA), "the name matches but the status does not");
    }

    /** The URL lists statuses in declaration order, whatever order they came in. */
    @Test
    void statusesAreKeptInDeclarationOrder() {
        CustomerFilter filter = new CustomerFilter("",
                Set.of(CustomerStatus.CLOSED, CustomerStatus.ACTIVE));
        assertEquals(List.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED),
                List.copyOf(filter.statuses()));
    }

    @Test
    void whitespaceIsNotSignificant() {
        assertEquals(List.of("ada", "aal"), new CustomerFilter(" ada  aal ", Set.of()).nameTerms());
        assertEquals(List.of(), new CustomerFilter("   ", Set.of()).nameTerms());
        assertTrue(new CustomerFilter("   ", Set.of()).isEmpty());
    }
}
