+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.Collections;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * What the customer list is narrowed down to, as {@link CustomerRepository}
+ * understands it.
+ *
+ * <p>Both parts are optional and {@link #EMPTY} matches every customer. The
+ * name query is split on whitespace into terms, and a customer matches when
+ * <em>every</em> term is a substring of its first or last name, ignoring case
+ * and accents. The statuses are a whitelist: empty means every status.
+ *
+ * @param name     the name query as the user typed it, whitespace trimmed
+ * @param statuses the statuses to show, in declaration order; empty means all
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** The filter that matches every customer. */
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name.trim();
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of()
+                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
+    }
+
+    /** Whether this filter narrows anything down at all. */
+    public boolean isEmpty() {
+        return name.isEmpty() && statuses.isEmpty();
+    }
+
+    /**
+     * This filter as a predicate, with the name query split and normalized
+     * once so that a whole query only pays for it a single time.
+     */
+    public Predicate<Customer> asPredicate() {
+        if (isEmpty()) {
+            return customer -> true;
+        }
+        List<String> terms = nameTerms();
+        return customer -> matchesStatus(customer) && matchesName(customer, terms);
+    }
+
+    /** The name query as normalized terms; empty when nothing was typed. */
+    public List<String> nameTerms() {
+        if (name.isEmpty()) {
+            return List.of();
+        }
+        return Arrays.stream(WHITESPACE.split(name))
+                .filter(term -> !term.isEmpty())
+                .map(CustomerFilter::normalize)
+                .toList();
+    }
+
+    private boolean matchesStatus(Customer customer) {
+        return statuses.isEmpty() || statuses.contains(customer.status());
+    }
+
+    private static boolean matchesName(Customer customer, List<String> terms) {
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String firstName = normalize(customer.firstName());
+        String lastName = normalize(customer.lastName());
+        return terms.stream()
+                .allMatch(term -> firstName.contains(term) || lastName.contains(term));
+    }
