+package com.example.customers;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.List;
+import java.util.Set;
+
+import com.example.customers.domain.CustomerRepository;
+import com.example.customers.domain.CustomerStatus;
+import com.example.customers.domain.QueryLog;
+
+import com.example.Application;
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Component;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.combobox.MultiSelectComboBox;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.grid.GridSortOrder;
+import com.vaadin.flow.component.html.Span;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.QueryParameters;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.boot.test.context.SpringBootTest;
+
+/** Filtering the customer list: what matches, what it says, what it costs. */
+@SpringBootTest(classes = Application.class,
+        webEnvironment = SpringBootTest.WebEnvironment.MOCK)
+class CustomerFilteringTest extends SpringBrowserlessTest {
+
+    @Autowired
+    private QueryLog queryLog;
+
+    private Grid<?> grid() {
+        return find(Grid.class).single();
+    }
+
+    private TextField nameFilter() {
+        return find(TextField.class).withPlaceholder("Filter by name").single();
+    }
+
+    @SuppressWarnings("unchecked")
+    private MultiSelectComboBox<CustomerStatus> statusFilter() {
+        return find(MultiSelectComboBox.class).withLabel("Status").single();
+    }
+
+    private String summary() {
+        return find(Span.class).single().getText();
+    }
+
+    @SuppressWarnings({"rawtypes", "unchecked"})
+    private void sortByLastName(boolean ascending) {
+        Grid raw = grid();
+        Grid.Column column = raw.getColumnByKey("lastName");
+        raw.sort(ascending
+                ? GridSortOrder.asc(column).build()
+                : GridSortOrder.desc(column).build());
+    }
+
+    /** Opens the view, optionally with a query string such as {@code name=vir}. */
+    private void open(String queryString) {
+        navigate("", Component.class);
+        if (!queryString.isEmpty()) {
+            UI.getCurrent().navigate("", QueryParameters.fromString(queryString));
+        }
+        queryLog.clear();
+    }
+
+    @Test
+    void filterStartsEmptyAndShowsEverything() {
+        open("");
+
+        assertEquals("", nameFilter().getValue());
+        assertEquals(Set.of(), statusFilter().getValue());
+        assertEquals(500, test(grid()).size());
+        assertEquals("Showing 500 of 500", summary());
+    }
+
+    @Test
+    void statusComboBoxOffersEveryStatus() {
+        open("");
+
+        assertEquals(List.of(CustomerStatus.values()),
+                test(statusFilter()).getSuggestionItems());
+    }
+
+    @Test
+    void nameFilterNarrowsTheList() {
+        open("");
+        test(nameFilter()).setValue("aaltonen");
+
+        assertTrue(test(grid()).size() > 0);
+        assertEquals("Aaltonen", test(grid()).getCellText(0, 1));
+        assertEquals("Showing " + test(grid()).size() + " of 500", summary());
+    }
+
+    @Test
+    void everyTermMustMatchInEitherOrder() {
+        open("");
+        test(nameFilter()).setValue("ada aal");
+        int forwards = test(grid()).size();
+        assertTrue(forwards >= 1);
+        assertEquals("Ada", test(grid()).getCellText(0, 0));
+
+        test(nameFilter()).setValue("  aal   ada  ");
+        assertEquals(forwards, test(grid()).size());
+
+        test(nameFilter()).setValue("ada virtanen");
+        assertEquals(0, test(grid()).size());
+        assertEquals("Showing 0 of 500", summary());
+    }
+
+    @Test
+    void matchingIgnoresCaseAndAccents() {
+        open("");
+        test(nameFilter()).setValue("mäkinen");
+        int accented = test(grid()).size();
+        assertTrue(accented > 0, "the data set should contain a Mäkinen");
+
+        test(nameFilter()).setValue("makinen");
+        assertEquals(accented, test(grid()).size());
+
+        test(nameFilter()).setValue("MAKINEN");
+        assertEquals(accented, test(grid()).size());
+    }
+
+    @Test
+    void statusFilterNarrowsTheList() {
+        open("");
+        statusFilter().setValue(Set.of(CustomerStatus.ACTIVE));
+
+        assertEquals(167, test(grid()).size());
+        assertEquals("Showing 167 of 500", summary());
+        assertEquals("ACTIVE", test(grid()).getCellText(0, 4));
+
+        statusFilter().setValue(Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED));
+        assertEquals(167 + 166, test(grid()).size());
+
+        statusFilter().clear();
+        assertEquals(500, test(grid()).size());
+    }
+
+    @Test
+    void bothFiltersApplyTogether() {
+        open("");
+        test(nameFilter()).setValue("a");
+        int byName = test(grid()).size();
+
+        statusFilter().setValue(Set.of(CustomerStatus.PENDING));
+        int byBoth = test(grid()).size();
+
+        assertTrue(byBoth < byName);
+        assertEquals("Showing " + byBoth + " of 500", summary());
+        for (int row = 0; row < Math.min(byBoth, 20); row++) {
+            assertEquals("PENDING", test(grid()).getCellText(row, 4));
+        }
+    }
+
+    @Test
+    void urlParametersApplyAndShowInTheFields() {
+        open("name=vir&status=ACTIVE,CLOSED");
+
+        assertEquals("vir", nameFilter().getValue());
+        assertEquals(Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED),
+                statusFilter().getValue());
+
+        int matching = test(grid()).size();
+        assertTrue(matching > 0);
+        assertEquals("Showing " + matching + " of 500", summary());
+        for (int row = 0; row < matching; row++) {
+            assertFalse("PENDING".equals(test(grid()).getCellText(row, 4)));
+            assertTrue((test(grid()).getCellText(row, 0) + test(grid()).getCellText(row, 1))
+                    .toLowerCase().contains("vir"));
+        }
+    }
+
+    /** The filter belongs in the backend: a filtered grid still holds one page. */
+    @Test
+    void filteringStaysLazy() {
+        open("");
+        test(nameFilter()).setValue("a");
+        test(grid()).getCellText(0, 0);
+
+        assertFalse(queryLog.pageQueries().isEmpty());
+        queryLog.pageQueries().forEach(page -> assertTrue(
+                page.limit() <= CustomerRepository.MAX_PAGE_SIZE,
+                "A page query asked for " + page.limit() + " rows"));
+        assertTrue(queryLog.rowsFetched() <= CustomerRepository.MAX_PAGE_SIZE,
+                "Filtering pulled " + queryLog.rowsFetched() + " rows over");
+    }
+
+    /** The matching count is the backend's answer, not the loaded row count. */
+    @Test
+    void theCountComesFromACountQuery() {
+        open("");
+        test(nameFilter()).setValue("aaltonen");
+        test(grid()).getCellText(0, 0);
+
+        int matching = test(grid()).size();
+        assertTrue(queryLog.countQueries().contains(matching),
+                "The backend was never asked how many customers match: "
+                        + queryLog.countQueries());
+        assertEquals("Showing " + matching + " of 500", summary());
+    }
+
+    /**
+     * A settled filter change is a count query and a page of rows, not a
+     * re-read of the table. (What a keystroke costs is a client-side matter,
+     * so it is {@code CustomerListViewBrowserTest} that measures that.)
+     */
+    @Test
+    void oneFilterChangeCostsOnePageOfRows() {
+        open("");
+        test(grid()).getCellText(0, 0);
+        queryLog.clear();
+
+        test(nameFilter()).setValue("aaltonen");
+        test(grid()).getCellText(0, 0);
+
+        assertTrue(queryLog.pageQueries().size() <= 2,
+                "page queries: " + queryLog.pageQueries());
+        assertTrue(queryLog.rowsFetched() <= CustomerRepository.MAX_PAGE_SIZE,
+                "Filtering pulled " + queryLog.rowsFetched() + " rows over");
+    }
+
+    @Test
+    void sortingKeepsWorkingWhileFiltered() {
+        open("");
+        test(nameFilter()).setValue("a");
+
+        sortByLastName(true);
+        String firstAscending = test(grid()).getCellText(0, 1);
+        int matching = test(grid()).size();
+
+        sortByLastName(false);
+        String firstDescending = test(grid()).getCellText(0, 1);
+
+        assertEquals(matching, test(grid()).size());
+        assertTrue(firstAscending.compareToIgnoreCase(firstDescending) < 0,
+                firstAscending + " should sort before " + firstDescending);
+        assertTrue(queryLog.rowsFetched() <= 3 * CustomerRepository.MAX_PAGE_SIZE);
+    }
+}
