+        page.waitForFunction("() => window.location.search.includes('name=virtanen')");
+
+        assertEquals("/?name=virtanen", pathAndQuery());
+
+        statusFilter().selectItems("ACTIVE", "CLOSED");
+        waitForVaadin();
+        page.waitForFunction("() => window.location.search.includes('status=')");
+        assertEquals("/?name=virtanen&status=ACTIVE,CLOSED", pathAndQuery());
+
+        assertEquals(historyLength, historyLength(),
+                "Typing must not push a history entry per keystroke");
+
+        // The link is the filter: reloading it keeps the narrowed list.
+        page.reload();
+        waitForVaadin();
+        nameFilter().assertValue("virtanen");
+        statusFilter().assertSelectedItems("ACTIVE", "CLOSED");
+        assertEquals("/?name=virtanen&status=ACTIVE,CLOSED", pathAndQuery());
+
+        // Clearing the filter leaves nothing behind.
+        statusFilter().deselectItems("ACTIVE", "CLOSED");
+        nameFilter().clear();
+        waitForVaadin();
+        page.waitForFunction("() => window.location.search === ''");
+        assertEquals("/", pathAndQuery());
+    }
+
+    /** Typing must not query the backend once per keystroke. */
+    @Test
+    void typingANameCostsOneOrTwoQueries() {
+        page.navigate(getUrl() + "/");
+        waitForVaadin();
+        GridElement grid = GridElement.get(page);
+        assertEquals(500, grid.getTotalRowCount());
+        queryLog.clear();
+
+        nameFilter().getInputLocator().click();
+        nameFilter().getInputLocator().pressSequentially("virtanen",
+                new Locator.PressSequentiallyOptions().setDelay(20));
+        waitForVaadin();
+        page.waitForFunction("() => window.location.search.includes('name=virtanen')");
+
+        assertTrue(grid.getTotalRowCount() > 0);
+        assertTrue(queryLog.countQueries().size() <= 2,
+                "Typing eight letters ran " + queryLog.countQueries().size()
+                        + " count queries: " + queryLog.countQueries());
+        assertTrue(queryLog.pageQueries().size() <= 2,
+                "Typing eight letters ran " + queryLog.pageQueries().size()
+                        + " page queries: " + queryLog.pageQueries());
+        assertTrue(queryLog.rowsFetched() <= CustomerRepository.MAX_PAGE_SIZE,
+                "Typing pulled " + queryLog.rowsFetched() + " rows over");
+    }
+
+    @Test
+    void theListFollowsTheTypingAndTheSummaryFollowsTheList() {
+        List<String> consoleErrors = new ArrayList<>();
+        page.onConsoleMessage(message -> {
+            if ("error".equals(message.type())) {
+                consoleErrors.add(message.text());
+            }
+        });
+        page.navigate(getUrl() + "/");
+        waitForVaadin();
+        GridElement grid = GridElement.get(page);
+        assertEquals("Showing 500 of 500", summary().first().textContent());
+
+        nameFilter().getInputLocator().click();
+        // No Enter, no blur: the list narrows on its own.
+        nameFilter().getInputLocator().pressSequentially("aaltonen",
+                new Locator.PressSequentiallyOptions().setDelay(20));
+        page.waitForFunction("() => document.body.innerText.includes('Showing')"
+                + " && !document.body.innerText.includes('Showing 500 of 500')");
+        waitForVaadin();
+
+        int matching = grid.getTotalRowCount();
+        assertTrue(matching > 0 && matching < 500);
+        assertEquals("Showing " + matching + " of 500", summary().first().textContent());
+        assertEquals("Aaltonen", grid.findCell(0, 1).orElseThrow()
+                .getCellContentLocator().textContent());
+        assertEquals(List.of(), consoleErrors, "The browser logged errors");
+    }
+
+    @Test
+    void sortingKeepsWorkingWhileFiltered() {
+        page.navigate(getUrl() + "/?name=a");
+        waitForVaadin();
+        GridElement grid = GridElement.get(page);
+        int matching = grid.getTotalRowCount();
+
+        GridElement.HeaderCellElement lastName =
+                grid.findHeaderCellByText("Last name").orElseThrow();
+        lastName.assertSortable();
+
+        lastName.clickSort();
+        waitForVaadin();
+        lastName.assertSortAscending();
+        String ascending = grid.findCell(0, 1).orElseThrow().getCellContentLocator().textContent();
+
+        lastName.clickSort();
+        waitForVaadin();
+        lastName.assertSortDescending();
+        String descending = grid.findCell(0, 1).orElseThrow().getCellContentLocator().textContent();
+
+        assertEquals(matching, grid.getTotalRowCount());
+        assertTrue(ascending.compareToIgnoreCase(descending) < 0,
+                ascending + " should sort before " + descending);
+    }
+
+    private int historyLength() {
+        return ((Number) page.evaluate("window.history.length")).intValue();
+    }
+
+    private String pathAndQuery() {
+        return (String) page.evaluate("window.location.pathname + window.location.search");
+    }
+}
